import os

from algo.dps import DPS


class Custom(DPS):
    # DPS (Chung et al., ICLR 2023): InverseBench's implementation, tuned per setting.

    # InverseBench (arXiv:2503.11043) appendix table tab:algo-parameters.
    GUIDANCE = {
        'inv-scatter': 280.0,
        'blackhole': 0.003,
        'blackhole-10pct': 0.003,
    }

    def __init__(self, net, forward_op, diffusion_scheduler_config=None,
                 guidance_scale=10.0, sde=True, **kwargs):
        guidance_scale = self.GUIDANCE.get(os.environ.get('ENV', ''), guidance_scale)
        diffusion_scheduler_config = diffusion_scheduler_config or {
            'num_steps': 1000, 'schedule': 'vp', 'timestep': 'vp', 'scaling': 'vp'}
        super().__init__(net, forward_op, diffusion_scheduler_config, guidance_scale, sde=sde)

import os

from algo.lgd import LGD


class Custom(LGD):
    # LGD (Song et al., ICML 2023): InverseBench's implementation, tuned per setting.

    # InverseBench (arXiv:2503.11043) appendix table tab:algo-parameters:
    # (guidance scale, number of MC samples).
    SETTINGS = {
        'inv-scatter': (3200.0, 20),
        'blackhole': (0.0082, 8),
        'blackhole-10pct': (0.0082, 8),
    }

    def __init__(self, net, forward_op, diffusion_scheduler_config=None,
                 guidance_scale=3e-3, num_samples=3, batch_grad=True, sde=True, **kwargs):
        guidance_scale, num_samples = self.SETTINGS.get(
            os.environ.get('ENV', ''), (guidance_scale, num_samples))
        diffusion_scheduler_config = diffusion_scheduler_config or {
            'num_steps': 1000, 'schedule': 'vp', 'timestep': 'vp', 'scaling': 'vp'}
        super().__init__(net, forward_op, diffusion_scheduler_config, guidance_scale,
                         num_samples=num_samples, batch_grad=batch_grad, sde=sde)
